1066	var FIELD=(function(){
1067	  var cv=document.getElementById('field'); if(!cv||!cv.getContext) return null;
1068	  var ctx=cv.getContext('2d'), DPR=Math.min(window.devicePixelRatio||1,1.6), W=1600,H=900;
1069	  cv.width=W*DPR; cv.height=H*DPR; ctx.scale(DPR,DPR);
1070	  var N=900, pts=[], running=false, show=true, ring=true, t0=0;
1071	  var reduce=window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
1072	  for (var i=0;i<N;i++){
1073	    var z=Math.random()*.8+.2, a=Math.random()*Math.PI*2, rr=i%3===0?230:(i%3===1?150:320);
1074	    pts.push({x:Math.random()*W,y:Math.random()*H,z:z,vx:(Math.random()-.5)*.35,vy:(Math.random()-.5)*.22,
1075	      ring:i<N*.42, tx:1230+Math.cos(a)*rr*(0.96+Math.random()*.08), ty:440+Math.sin(a)*rr*(0.96+Math.random()*.08), ph:Math.random()*6.28});
1076	  }
1077	  function frame(ts){
1078	    if (!running) return;
1079	    var t=ts/1000; ctx.clearRect(0,0,W,H);
1080	    for (var i=0;i<N;i++){
1081	      var p=pts[i];
1082	      if (ring && p.ring){
1083	        var ang=t*.05*(p.z>.6?1:-1), cx=1230, cy=440, dx=p.tx-cx, dy=p.ty-cy;
1084	        var gx=cx+dx*Math.cos(ang)-dy*Math.sin(ang), gy=cy+dx*Math.sin(ang)+dy*Math.cos(ang);
1085	        p.x+=(gx-p.x)*.03; p.y+=(gy-p.y)*.03;
1086	      } else {
1087	        p.x+=p.vx*p.z*1.4; p.y+=p.vy*p.z*1.4;
1088	        if(p.x<-10)p.x=W+10; if(p.x>W+10)p.x=-10; if(p.y<-10)p.y=H+10; if(p.y>H+10)p.y=-10;
1089	      }
1090	      var al=(.18+.55*p.z)*(.75+.25*Math.sin(t*1.3+p.ph));
1091	      ctx.fillStyle=p.ring&&ring ? 'rgba(143,180,236,'+al+')' : 'rgba(195,215,238,'+(al*.8)+')';
1092	      ctx.beginPath(); ctx.arc(p.x,p.y,.6+1.5*p.z,0,6.283); ctx.fill();
1093	    }
1094	    requestAnimationFrame(frame);
1095	  }
1096	  function start(){ if(!running && show && !reduce && !document.hidden && !root.classList.contains('mobile')){ running=true; requestAnimationFrame(frame);} }
1097	  function stop(){ running=false; }
1098	  document.addEventListener('visibilitychange',function(){ document.hidden?stop():start(); });
1099	  if (reduce){ /* um quadro estático */ ctx.fillStyle='rgba(195,215,238,.4)'; pts.forEach(function(p){ctx.beginPath();ctx.arc(p.x,p.y,1,0,6.283);ctx.fill();}); }
1100	  return { setMode:function(dark,r){ show=dark; ring=r; if(show) start(); else { stop(); ctx.clearRect(0,0,W,H);} } };
1101	})();
